stylesheet:
a:link,
a:visited {
	color: #7289da;
}

a:hover,
a:active {
	color: #b56ac4;
}

#content {
	color: #d3d3d3;
}

.tborder {
	background: #161616;
	border-color: #0d0d0d;
}

.thead {
	background: #262832;
	border-bottom-color: #101116;
	box-shadow: inset 0 0 1px 1px #3a3d4c;
}

.tcat {
	background: #202020;
	border-top-color: #111;
	border-bottom-color: #303030;
}

.trow1 {
	background: #181818;
}

.trow2 {
	background: #1c1c1c;
}

.trow1,
.trow2 {
	border-top-color: #101010;
	border-bottom-color: #292929;
}

.trow_shaded,
.trow_selected,
tr.trow_selected td {
	background: #23232a;
}

input.textbox:focus,
textarea:focus,
select:focus {
	border-color: #667bc4;
	box-shadow: 0 0 0 1px #262832;
	outline: 0;
}

input.button,
button,
.button {
	background: #262832;
	border-color: #3a3d4c;
}

input.button:hover,
button:hover,
.button:hover {
	background: #667bc4;
	border-color: #7289da;
}

.pagination a:hover,
.pagination .pagination_current {
	background: #667bc4;
	border-color: #7289da;
	color: #fff;
}

blockquote,
.codeblock {
	background: #141414;
	border-color: #262832;
}
